DROP TABLE IF EXISTS `xwq_ai_image`;
CREATE TABLE `xwq_ai_image`  (
  `image_id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '唯一标识一张图片',
  `image_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '图片原始名称',
  `image_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '图片存储地址',
  `image_result_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '模型识别后的打框图、标注图地址',
  `image_mask_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '分割 mask 图片地址',
  `image_ai_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '识别业务类型：disease 病虫害，pest 虫情，phenology 物候期，unknown 未知',
  `image_source` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '图片来源：手动上传、摄像头、虫情设备、无人机、手机端',
  `image_source_id` bigint(0) DEFAULT NULL COMMENT '来源设备 ID、摄像头 ID、任务 ID 等',
  `image_width` int(0) DEFAULT NULL COMMENT '图片宽度，单位像素',
  `image_height` int(0) DEFAULT NULL COMMENT '图片高度，单位像素',
  `image_size` bigint(0) DEFAULT NULL COMMENT '图片大小，单位字节',
  `image_format` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '图片格式，如 jpg、png、jpeg',
  `park_id` bigint(0) DEFAULT NULL COMMENT '园区 ID',
  `plot_id` bigint(0) DEFAULT NULL COMMENT '地块 ID',
  `device_id` bigint(0) DEFAULT NULL COMMENT '设备 ID，关联摄像头、虫情测报仪等设备',
  `longitude` decimal(10, 7) DEFAULT NULL COMMENT '图片采集位置经度',
  `latitude` decimal(10, 7) DEFAULT NULL COMMENT '图片采集位置纬度',
  `image_status` tinyint(0) NOT NULL DEFAULT 0 COMMENT '图片状态：0 待识别，1 已识别，2 识别失败',
  `image_a` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备用字段1',
  `image_b` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备用字段2',
  `image_c` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备用字段3',
  `image_d` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备用字段4',
  `image_e` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备用字段5',
  `image_f` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备用字段6',
  `image_g` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备用字段7',
  `image_h` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备用字段8',
  `image_i` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备用字段9',
  `image_j` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备用字段10',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`image_id`) USING BTREE,
  INDEX `idx_image_ai_type`(`image_ai_type`) USING BTREE,
  INDEX `idx_image_source`(`image_source`) USING BTREE,
  INDEX `idx_image_source_id`(`image_source_id`) USING BTREE,
  INDEX `idx_image_park_id`(`park_id`) USING BTREE,
  INDEX `idx_image_plot_id`(`plot_id`) USING BTREE,
  INDEX `idx_image_device_id`(`device_id`) USING BTREE,
  INDEX `idx_image_status`(`image_status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9039 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '图片信息表' ROW_FORMAT = Dynamic;

